#!/usr/bin/env node
// Level lists (owner, 2026-11-21): which cards and items each tier (act) may offer, from the combat-power table and
// scoring.json levelLists.tiers. Writes src/content/generated/levelLists.js.
//
//   node tools/level-lists.mjs            # rewrite the generated file
//   node tools/level-lists.mjs --check    # exit 1 when it is stale (npm run level-lists:check)
//
// Run after `npm run combat-power`: the lists read src/content/generated/combatPower.js.
import { writeFileSync, readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { buildLevelLists } from '../src/model/levelLists.js';

const OUT = fileURLToPath(new URL('../src/content/generated/levelLists.js', import.meta.url));
const lines = (ids, pad) => '[\n' + ids.map((id) => pad + ' ' + JSON.stringify(id)).join(',\n') + '\n' + pad + ']';

export function render(lists = buildLevelLists()) {
  const cards = Object.entries(lists.cards).map(([t, ids]) => ` ${JSON.stringify(t)}: ${lines(ids, ' ')}`).join(',\n');
  const items = Object.entries(lists.items).map(([t, kinds]) => ` ${JSON.stringify(t)}: {\n`
    + Object.entries(kinds).map(([k, ids]) => `  ${JSON.stringify(k)}: ${lines(ids, '  ')}`).join(',\n') + '\n }').join(',\n');
  return '// GENERATED by tools/level-lists.mjs from content/source/scoring.json levelLists and src/content/generated/combatPower.js\n'
    + '// Do not edit by hand: run `npm run level-lists` (`npm run level-lists:check` fails when this file is stale).\n'
    + '// Ids whose combat-power rank is inside each tier band; a band that would be empty lists every id of its kind.\n\n'
    + 'export const levelLists = {\n cards: {\n' + cards.replace(/^/gm, ' ') + '\n },\n items: {\n' + items.replace(/^/gm, ' ') + '\n }\n};\n';
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (process.argv.includes('--check')) {
    const current = existsSync(OUT) ? readFileSync(OUT, 'utf8') : '';
    if (current !== render()) { console.error('src/content/generated/levelLists.js is stale: run `npm run level-lists`'); process.exit(1); }
    console.log('level-lists: generated file is fresh');
  } else {
    writeFileSync(OUT, render());
    console.log(`wrote ${OUT}`);
  }
}
